"""Declarative OTel metric instrument specifications.

Domain packages (e.g. ``rasa.tracing.voice.metrics``) declare one
:class:`InstrumentSpec` per instrument and derive everything else from it:
the instrument itself (:meth:`InstrumentSpec.create`) and the SDK View that
enforces the attribute allowlist and histogram buckets at export time
(:meth:`InstrumentSpec.to_view`). Keeping both derived from one spec means
the enforced allowlist can never drift from the declaration.
"""

from __future__ import annotations

from enum import Enum
from typing import FrozenSet, Optional, Tuple, Union

from opentelemetry.metrics import Counter, Histogram, Meter
from opentelemetry.sdk.metrics.view import ExplicitBucketHistogramAggregation, View
from pydantic import BaseModel, ConfigDict, model_validator


class InstrumentKind(Enum):
    """OTel instrument type used for a metric."""

    HISTOGRAM = "histogram"
    COUNTER = "counter"


class InstrumentSpec(BaseModel):
    """Complete declarative definition of one metric instrument.

    The spec is the single source of truth for the instrument: registration
    (:meth:`create`) and the export-time attribute allowlist plus histogram
    buckets (:meth:`to_view`) both derive from it.
    """

    model_config = ConfigDict(frozen=True)

    name: str
    kind: InstrumentKind
    unit: str
    description: str
    allowed_attribute_keys: FrozenSet[str]
    # Required for histograms, forbidden for counters.
    bucket_boundaries_s: Optional[Tuple[float, ...]] = None

    @model_validator(mode="after")
    def _validate_buckets_match_kind(self) -> "InstrumentSpec":
        if self.kind is InstrumentKind.HISTOGRAM and self.bucket_boundaries_s is None:
            raise ValueError(
                f"Histogram instrument '{self.name}' must declare "
                f"explicit bucket boundaries."
            )
        if self.kind is InstrumentKind.COUNTER and self.bucket_boundaries_s is not None:
            raise ValueError(
                f"Counter instrument '{self.name}' must not declare "
                f"bucket boundaries."
            )
        return self

    def to_view(self) -> View:
        """Build the SDK View enforcing this spec at export time."""
        aggregation = (
            ExplicitBucketHistogramAggregation(self.bucket_boundaries_s)
            if self.bucket_boundaries_s is not None
            else None
        )
        return View(
            instrument_name=self.name,
            attribute_keys=set(self.allowed_attribute_keys),
            aggregation=aggregation,
        )

    def create(self, meter: Meter) -> Union[Histogram, Counter]:
        """Create the instrument on the given meter."""
        if self.kind is InstrumentKind.HISTOGRAM:
            return meter.create_histogram(
                name=self.name, description=self.description, unit=self.unit
            )
        return meter.create_counter(
            name=self.name, description=self.description, unit=self.unit
        )
